{
  "page": {
    "use": "page/basic",
    "data": {
      "title": "Join Larkspur Supply Co.",
      "site": "Larkspur Supply Co.",
      "description": "Join Larkspur Supply Co. with a one-time $30 lifetime membership.",
      "heading": "Join Larkspur Supply Co."
    },
    "slots": {
      "main": [
        {
          "use": "content/prose",
          "key": "intro",
          "data": { "html": "<p>A one-time $30 lifetime membership.</p>" }
        },
        {
          "use": "form/form",
          "key": "signup",
          "data": { "method": "post", "label": "Sign-up form" },
          "slots": {
            "fields": [
              { "use": "form/text-field", "key": "name", "data": { "label": "Full name", "name": "name", "autocomplete": "name", "required": true } },
              { "use": "form/text-field", "key": "email", "data": { "label": "Email", "name": "email", "type": "email", "autocomplete": "email", "required": true } },
              { "use": "form/text-field", "key": "password", "data": { "label": "Password", "name": "password", "type": "password", "autocomplete": "new-password", "required": true, "hint": "At least 12 characters" } },
              { "use": "form/text-field", "key": "phone", "data": { "label": "Phone (optional)", "name": "phone", "type": "tel", "autocomplete": "tel" } },
              {
                "use": "form/checkbox-group",
                "key": "interests",
                "data": {
                  "legend": "Interests",
                  "name": "interests",
                  "hint": "Choose any",
                  "choices": [
                    { "value": "hiking", "label": "Hiking" },
                    { "value": "paddling", "label": "Paddling" },
                    { "value": "climbing", "label": "Climbing" },
                    { "value": "winter-travel", "label": "Winter travel" }
                  ]
                }
              },
              { "use": "form/checkbox", "key": "newsletter", "data": { "label": "Send me the monthly newsletter", "name": "newsletter" } },
              { "use": "form/checkbox", "key": "terms", "data": { "label": "I agree to the <a href=\"/terms\">member terms</a>", "name": "terms", "required": true } }
            ],
            "actions": [
              { "use": "action/submit", "key": "join", "data": { "label": "Join and pay $30" } }
            ]
          }
        },
        {
          "use": "content/prose",
          "key": "signin",
          "data": { "html": "<p>Already a member? <a href=\"/sign-in\">Sign in</a></p>" }
        }
      ]
    }
  }
}

